@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: oklch(51.3% 0.17 254); /* #1868DB */
  --primary-hover: oklch(45% 0.17 254);
  --accent: oklch(65% 0.22 35); /* #FF613D */
  --accent-hover: oklch(60% 0.22 35);
  --text-dark: oklch(25% 0.01 265); /* #292A2E */
  --text-muted: oklch(50% 0.01 265);
  --surface: oklch(100% 0 0); /* #FFFFFF */
  --surface-muted: oklch(98% 0.01 254);
  --border: oklch(90% 0.01 254);
  --success: oklch(65% 0.15 150);

  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', sans-serif;
  color: var(--text-dark);
  background-color: var(--surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover {
  color: var(--primary-hover);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  color: var(--text-dark);
  line-height: 1.2;
  font-weight: 700;
  margin-bottom: 1rem;
}

h1 { font-size: 3.5rem; letter-spacing: -0.02em; }
h2 { font-size: 2.5rem; letter-spacing: -0.01em; }
h3 { font-size: 1.75rem; }
h4 { font-size: 1.25rem; }
p { margin-bottom: 1rem; color: var(--text-muted); font-size: 1.125rem; }
.text-small { font-size: 0.875rem; }

/* Layout */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 96px 0;
}

.section-muted {
  background-color: var(--surface-muted);
}

.text-center { text-align: center; }
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-8 { margin-bottom: 2rem; }
.mb-12 { margin-bottom: 3rem; }
.mt-4 { margin-top: 1rem; }
.mt-8 { margin-top: 2rem; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  font-size: 1rem;
  text-decoration: none;
}

.btn-primary {
  background-color: var(--primary);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  color: white;
  transform: translateY(-1px);
}

.btn-outline {
  background-color: transparent;
  color: var(--text-dark);
  border: 1px solid var(--border);
}

.btn-outline:hover {
  border-color: var(--text-dark);
  color: var(--text-dark);
}

.btn-block {
  width: 100%;
}

.badge {
  display: inline-block;
  padding: 4px 12px;
  background-color: var(--accent);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
}

/* Header & Nav */
.header {
  position: sticky;
  top: 0;
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
  z-index: 100;
  padding: 16px 0;
}

.header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text-dark);
  display: flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background-color: var(--primary);
  border-radius: 8px;
  display: inline-block;
}

.nav-links {
  display: flex;
  gap: 32px;
  align-items: center;
}

.nav-links a {
  color: var(--text-dark);
  font-weight: 500;
}

.nav-links a:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  gap: 16px;
  align-items: center;
}

/* Hero Section */
.hero {
  padding: 120px 0 80px;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 2.5rem;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
}

/* Logo Bar */
.logo-bar {
  padding: 48px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.logo-bar-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.logo-bar p {
  font-size: 1rem;
  font-weight: 500;
  margin: 0;
}

.logos {
  display: flex;
  flex-wrap: wrap;
  gap: 48px;
  justify-content: center;
  opacity: 0.6;
}

/* Feature Grid (2 col) */
.feature-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feature-row.reverse .feature-content {
  order: 2;
}

.feature-row.reverse .feature-visual {
  order: 1;
}

.feature-visual {
  background-color: var(--surface-muted);
  border-radius: var(--radius-lg);
  aspect-ratio: 4/3;
  width: 100%;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  position: relative;
}

/* Grid Layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }

/* Cards */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: box-shadow 0.2s, transform 0.2s;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-icon {
  width: 48px;
  height: 48px;
  background-color: var(--surface-muted);
  border-radius: var(--radius-md);
  margin-bottom: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
}

/* Pricing Cards */
.pricing-card {
  display: flex;
  flex-direction: column;
  height: 100%;
}
.pricing-card.popular {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  position: relative;
}
.pricing-card.popular::before {
  content: 'MOST POPULAR';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: var(--radius-full);
}
.pricing-price {
  font-size: 3rem;
  font-weight: 800;
  color: var(--text-dark);
  margin: 16px 0 8px;
}
.pricing-period {
  font-size: 1rem;
  color: var(--text-muted);
  font-weight: 500;
}
.pricing-features {
  list-style: none;
  margin: 32px 0;
  flex-grow: 1;
}
.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 16px;
  color: var(--text-dark);
}
.pricing-features li::before {
  content: '✓';
  color: var(--success);
  font-weight: bold;
}

/* Toggle */
.toggle-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin: 32px 0 48px;
}
.toggle-switch {
  position: relative;
  display: inline-block;
  width: 52px;
  height: 28px;
}
.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}
.toggle-slider {
  position: absolute;
  cursor: pointer;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--border);
  transition: .4s;
  border-radius: 34px;
}
.toggle-slider:before {
  position: absolute;
  content: "";
  height: 20px;
  width: 20px;
  left: 4px;
  bottom: 4px;
  background-color: white;
  transition: .4s;
  border-radius: 50%;
}
input:checked + .toggle-slider {
  background-color: var(--primary);
}
input:checked + .toggle-slider:before {
  transform: translateX(24px);
}
.save-badge {
  background-color: var(--success);
  color: white;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  margin-left: 8px;
}

/* Range Slider */
.slider-container {
  max-width: 600px;
  margin: 0 auto 64px;
  text-align: center;
}
.team-slider {
  width: 100%;
  margin: 16px 0;
}

/* FAQ Accordion */
.accordion {
  max-width: 800px;
  margin: 0 auto;
}
.accordion-item {
  border-bottom: 1px solid var(--border);
}
.accordion-header {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 24px 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-dark);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.accordion-content {
  padding-bottom: 24px;
  display: none;
  color: var(--text-muted);
}
.accordion-item.active .accordion-content {
  display: block;
}
.accordion-item.active .accordion-header::after {
  content: '−';
}
.accordion-header::after {
  content: '+';
  font-size: 1.5rem;
  font-weight: 400;
}

/* Testimonials */
.testimonial-card {
  background: var(--surface);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow-md);
  height: 100%;
}
.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--text-dark);
  margin-bottom: 24px;
}
.testimonial-author {
  font-weight: 600;
}
.testimonial-role {
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* CTA Banner */
.cta-banner {
  background-color: var(--primary);
  color: white;
  text-align: center;
  padding: 80px 0;
  border-radius: var(--radius-lg);
  margin: 64px 24px;
}
.cta-banner h2 {
  color: white;
}
.cta-banner p {
  color: rgba(255,255,255,0.8);
}
.cta-banner .btn-primary {
  background-color: white;
  color: var(--primary);
}
.cta-banner .btn-primary:hover {
  background-color: var(--surface-muted);
}

/* Auth Forms */
.auth-container {
  display: flex;
  min-height: 100vh;
}
.auth-form-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 40px 24px;
}
.auth-form {
  width: 100%;
  max-width: 400px;
}
.auth-sidebar {
  flex: 1;
  background-color: var(--surface-muted);
  display: none;
  padding: 64px;
  flex-direction: column;
  justify-content: center;
}
@media(min-width: 900px) {
  .auth-sidebar { display: flex; }
}
.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 12px;
  margin-bottom: 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: white;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s;
  color: var(--text-dark);
}
.social-btn:hover {
  background: var(--surface-muted);
}
.divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 24px 0;
  color: var(--text-muted);
  font-size: 0.875rem;
}
.divider::before, .divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--border);
}
.divider:not(:empty)::before { margin-right: .25em; }
.divider:not(:empty)::after { margin-left: .25em; }
.form-group {
  margin-bottom: 24px;
}
.form-control {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-family: inherit;
}
.form-control:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(24, 104, 219, 0.1);
}

/* Footer */
.footer {
  background-color: var(--surface-muted);
  padding: 80px 0 40px;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 64px;
}
.footer-col h4 {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-dark);
  margin-bottom: 16px;
}
.footer-col ul {
  list-style: none;
}
.footer-col li {
  margin-bottom: 12px;
}
.footer-col a {
  color: var(--text-muted);
  font-size: 0.875rem;
}
.footer-col a:hover {
  color: var(--primary);
}
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: var(--text-dark);
  color: white;
  padding: 24px;
  z-index: 1000;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transform: translateY(100%);
  transition: transform 0.3s ease-out;
}
.cookie-banner.visible {
  transform: translateY(0);
}
.cookie-content p {
  color: rgba(255,255,255,0.8);
  margin: 0;
  font-size: 0.875rem;
}
.cookie-actions {
  display: flex;
  gap: 16px;
}
.cookie-actions .btn-outline {
  border-color: rgba(255,255,255,0.3);
  color: white;
}

.cookie-modal {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  display: none;
  justify-content: center;
  align-items: center;
  z-index: 1001;
}
.cookie-modal.visible {
  display: flex;
}
.cookie-modal-content {
  background: white;
  padding: 32px;
  border-radius: var(--radius-lg);
  width: 90%;
  max-width: 500px;
}

/* Responsive */
@media(max-width: 1024px) {
  h1 { font-size: 2.75rem; }
  h2 { font-size: 2rem; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media(max-width: 768px) {
  .section { padding: 64px 0; }
  .nav-links, .nav-actions { display: none; } /* Mobile menu simplified */
  .feature-row { grid-template-columns: 1fr; gap: 32px; text-align: center; }
  .feature-row.reverse .feature-content { order: 1; }
  .feature-row.reverse .feature-visual { order: 2; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .cookie-banner { flex-direction: column; gap: 16px; text-align: center; }
  .cookie-actions { flex-direction: column; width: 100%; }
}

/* Comparison Table */
.comparison-table-wrapper {
  overflow-x: auto;
  margin-top: 48px;
}
.comparison-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 800px;
}
.comparison-table th, .comparison-table td {
  padding: 16px;
  border-bottom: 1px solid var(--border);
  text-align: left;
}
.comparison-table th {
  font-weight: 600;
  color: var(--text-dark);
  background: var(--surface-muted);
}
.comparison-table td {
  color: var(--text-muted);
}
.comparison-table .feature-name {
  color: var(--text-dark);
  font-weight: 500;
}
.expand-table-btn {
  margin-top: 24px;
  display: none;
}

/* Utilities */
.visually-hidden {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); border: 0;
}

document.addEventListener('DOMContentLoaded', () => {
  // Cookie Banner Logic
  const cookieBanner = document.getElementById('cookieBanner');
  if (cookieBanner && !localStorage.getItem('cookieConsent')) {
    setTimeout(() => {
      cookieBanner.classList.add('visible');
    }, 1000);
  }

  const acceptCookies = document.getElementById('acceptCookies');
  const rejectCookies = document.getElementById('rejectCookies');
  const manageCookies = document.getElementById('manageCookies');
  const cookieModal = document.getElementById('cookieModal');
  const savePreferences = document.getElementById('savePreferences');

  if (acceptCookies) {
    acceptCookies.addEventListener('click', () => {
      localStorage.setItem('cookieConsent', 'accepted');
      cookieBanner.classList.remove('visible');
    });
  }

  if (rejectCookies) {
    rejectCookies.addEventListener('click', () => {
      localStorage.setItem('cookieConsent', 'rejected');
      cookieBanner.classList.remove('visible');
    });
  }

  if (manageCookies && cookieModal) {
    manageCookies.addEventListener('click', () => {
      cookieModal.classList.add('visible');
    });
  }

  if (savePreferences && cookieModal) {
    savePreferences.addEventListener('click', () => {
      localStorage.setItem('cookieConsent', 'custom');
      cookieModal.classList.remove('visible');
      cookieBanner.classList.remove('visible');
    });
  }
});

document.addEventListener('DOMContentLoaded', () => {
  // Pricing Toggle Logic
  const billingToggle = document.getElementById('billingToggle');
  const priceBusiness = document.getElementById('priceBusiness');
  const priceBusinessAI = document.getElementById('priceBusinessAI');
  const periodLabels = document.querySelectorAll('.pricing-period');

  if (billingToggle) {
    billingToggle.addEventListener('change', (e) => {
      const isAnnual = e.target.checked;

      if (isAnnual) {
        if (priceBusiness) priceBusiness.textContent = '$15'; // ~17% off 18
        if (priceBusinessAI) priceBusinessAI.textContent = '$20'; // ~17% off 24
        periodLabels.forEach(el => el.textContent = 'per user / month, billed annually');
      } else {
        if (priceBusiness) priceBusiness.textContent = '$18';
        if (priceBusinessAI) priceBusinessAI.textContent = '$24';
        periodLabels.forEach(el => el.textContent = 'per user / month');
      }
    });
  }

  // FAQ Accordion
  const accordionHeaders = document.querySelectorAll('.accordion-header');
  accordionHeaders.forEach(header => {
    header.addEventListener('click', () => {
      const item = header.parentElement;
      const isActive = item.classList.contains('active');

      // Close all
      document.querySelectorAll('.accordion-item').forEach(el => el.classList.remove('active'));

      if (!isActive) {
        item.classList.add('active');
      }
    });
  });

  // Table Expand (Optional based on design)
  const expandTableBtn = document.getElementById('expandTableBtn');
  const comparisonTable = document.getElementById('comparisonTableWrapper');
  if (expandTableBtn && comparisonTable) {
    expandTableBtn.addEventListener('click', () => {
      comparisonTable.classList.toggle('expanded');
    });
  }

  // Team Size Slider Logic
  const teamSlider = document.getElementById('teamSlider');
  const teamSizeDisplay = document.getElementById('teamSizeDisplay');
  const recommendedPlan = document.getElementById('recommendedPlan');

  if (teamSlider) {
    teamSlider.addEventListener('input', (e) => {
      const value = parseInt(e.target.value, 10);
      if (teamSizeDisplay) {
        teamSizeDisplay.textContent = value + (value === 500 ? '+' : '');
      }
      if (recommendedPlan) {
        if (value < 10) {
          recommendedPlan.textContent = 'Starter or Business';
        } else if (value < 50) {
          recommendedPlan.textContent = 'Business + AI';
        } else {
          recommendedPlan.textContent = 'Enterprise';
        }
      }
    });
  }
});

